import{_ as r,C as o,o as n,c as l,a3 as a,E as s}from"./chunks/framework.CZBGEXos.js";const k=JSON.parse('{"title":"Початок роботи","description":"","frontmatter":{},"headers":[],"relativePath":"uk/getting-started.md","filePath":"uk/getting-started.md"}'),i={name:"uk/getting-started.md"};function d(h,t,p,c,m,u){const e=o("Screenshot");return n(),l("div",null,[t[0]||(t[0]=a('<h1 id="початок-роботи" tabindex="-1">Початок роботи <a class="header-anchor" href="#початок-роботи" aria-label="Permalink to &quot;Початок роботи&quot;">​</a></h1><p>Sentaro — це десктопний застосунок для моніторингу криптовалют під Windows. Він читає загальнодоступні ринкові дані з Bybit, Binance, Gate.io, OKX та Hyperliquid (а також Kraken spot у <a href="/manual/uk/tools/ticks.html">Ticks</a>) і показує їх через набір інструментів, кожен з яких відкривається у власному вікні зі змінним розміром.</p><h2 id="встановлення" tabindex="-1">Встановлення <a class="header-anchor" href="#встановлення" aria-label="Permalink to &quot;Встановлення&quot;">​</a></h2><ol><li>Завантажте інсталятор кнопкою <strong>Download</strong> на <a href="https://sentaro.trade/" target="_blank" rel="noreferrer">sentaro.trade</a>.</li><li>Запустіть <code>.exe</code>.</li><li>Sentaro працює тільки на Windows. Збірок для macOS чи Linux немає.</li></ol><h3 id="попередження-smartscreen" tabindex="-1">Попередження SmartScreen <a class="header-anchor" href="#попередження-smartscreen" aria-label="Permalink to &quot;Попередження SmartScreen&quot;">​</a></h3><p>При першому завантаженні та запуску <strong>Windows Defender SmartScreen може попередити, що застосунок нерозпізнаний</strong>. Це очікувано і не є виявленням вірусу.</p><p>SmartScreen позначає будь-яку нову програму, яка ще не здобула репутацію в Microsoft — це лише означає, що файл завантажило замало людей, щоб довіряти йому автоматично. Через це проходить кожен новий незалежний застосунок, і попередження зникає само, коли кількість завантажень зростає.</p><p>Щоб його пройти:</p><ol><li>Натисніть <strong>Докладніше</strong> у вікні SmartScreen.</li><li>Натисніть <strong>Все одно запустити</strong>.</li><li>Це буває лише один раз — наступні запуски попередження не покажуть.</li></ol><h2 id="першии-запуск" tabindex="-1">Перший запуск <a class="header-anchor" href="#першии-запуск" aria-label="Permalink to &quot;Перший запуск&quot;">​</a></h2><p>Під час запуску Sentaro спершу перевіряє оновлення, а тоді просить увійти.</p><h3 id="акаунт" tabindex="-1">Акаунт <a class="header-anchor" href="#акаунт" aria-label="Permalink to &quot;Акаунт&quot;">​</a></h3><p>Sentaro використовує акаунт з email і паролем. При реєстрації на пошту надсилається 6-значний код підтвердження; введіть його, щоб підтвердити адресу, і після цього увійдіть. Також під час реєстрації потрібно прийняти Умови надання послуг.</p><p>Доступ наразі безкоштовний, поки Sentaro у беті. Після входу вкладка <strong>Home</strong> показує статус підписки як <code>Beta Test</code>, а також ваш email і встановлену версію застосунку. Email за замовчуванням прихований — натисніть іконку ока поруч, щоб його показати.</p><div class="tip custom-block"><p class="custom-block-title">Sentaro не має доступу до ваших біржових акаунтів</p><p>Усі інструменти моніторингу читають лише публічні ринкові дані. Sentaro не запитує API ключі бірж, не підключається до вашого акаунта і не може виставляти ордери на жодній з бірж, які він відстежує.</p><p>Єдиний виняток — експериментальний <a href="/manual/uk/tools/terminal.html">Terminal</a>, окремий інструмент, який ви вмикаєте самі й підключаєте до Hyperliquid, Binance чи Bybit власними ключами. Без вашого свідомого налаштування він не робить нічого.</p></div><h2 id="робочии-простір" tabindex="-1">Робочий простір <a class="header-anchor" href="#робочии-простір" aria-label="Permalink to &quot;Робочий простір&quot;">​</a></h2>',16)),s(e,{src:"workspace",alt:"Робочий простір Sentaro з кількома відкритими вікнами інструментів",caption:"Робочий простір Sentaro — кілька вікон інструментів навколо головного вікна"}),t[1]||(t[1]=a('<p>Sentaro побудований навколо одного невеликого <strong>головного вікна</strong> плюс по вікну на кожен інструмент.</p><p>Ліворуч у головному вікні — вертикальна панель вкладок:</p><table tabindex="0"><thead><tr><th>Вкладка</th><th>Що містить</th></tr></thead><tbody><tr><td>Home</td><td>Акаунт, мова, акцентний колір, налаштування графіків і рисування</td></tr><tr><td>Knives</td><td>Налаштування <a href="/manual/uk/tools/knives.html">Knives</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Alerts</td><td>Налаштування <a href="/manual/uk/tools/alerts.html">Alerts</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Analyzer</td><td>Примітки <a href="/manual/uk/tools/analyzer.html">Analyzer</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Monitor</td><td>Налаштування <a href="/manual/uk/tools/monitor.html">Monitor</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Terminal</td><td>Налаштування <a href="/manual/uk/tools/terminal.html">Terminal</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Ticks</td><td>Налаштування <a href="/manual/uk/tools/ticks.html">Ticks</a> + кнопка <strong>Open Window</strong></td></tr></tbody></table><p>Усі інструменти працюють однаково: <strong>налаштування живуть у головному вікні, а сам інструмент відкривається окремим вікном.</strong> Натисніть <strong>Open Window</strong> у вкладці інструмента, щоб його запустити. Поки те вікно відкрите, кнопка показує <strong>Already Open</strong> і неактивна — кожен інструмент може мати лише одне вікно.</p><p>Оскільки кожен інструмент — незалежне вікно, ви можете вільно змінювати їхній розмір і розташування, будуючи потрібну розкладку, а головне вікно прибрати вбік.</p><p>Зміни налаштувань застосовуються наживо — відкрите вікно інструмента підхоплює їх без перезапуску. Налаштування записуються на диск автоматично.</p><h3 id="заголовок-вікна" tabindex="-1">Заголовок вікна <a class="header-anchor" href="#заголовок-вікна" aria-label="Permalink to &quot;Заголовок вікна&quot;">​</a></h3><p>Вікна інструментів мають власний заголовок Sentaro замість віндовського. Ліворуч у ньому <code>SENTARO</code> і назва активного інструмента, праворуч — згорнути / розгорнути / закрити. Щоб пересунути вікно, тягніть за будь-яке порожнє місце смуги.</p><h2 id="мова" tabindex="-1">Мова <a class="header-anchor" href="#мова" aria-label="Permalink to &quot;Мова&quot;">​</a></h2><p>Інтерфейс Sentaro доступний англійською, українською та російською. Перемкнути можна у вкладці <strong>Home</strong>, вгорі праворуч біля заголовка SENTARO. Це налаштування не пов&#39;язане з мовою, якою ви читаєте цей довідник.</p><h2 id="повідомлення-про-помилки" tabindex="-1">Повідомлення про помилки <a class="header-anchor" href="#повідомлення-про-помилки" aria-label="Permalink to &quot;Повідомлення про помилки&quot;">​</a></h2><p>Коли щось іде не так — потік даних від&#39;єднався, вікно не відкрилося, збережені налаштування не завантажились — у правому нижньому куті відповідного вікна з&#39;являється коротке повідомлення. Воно зникає саме за кілька секунд, або натисніть <strong>×</strong>, щоб закрити його. Те саме повідомлення показується не частіше ніж раз на 15 секунд, тож з&#39;єднання, що раз у раз перепідключається, не засипле екран.</p><p>Якщо помилка повертається знову й знову, напишіть про неї в <a href="https://t.me/sentaro_trade" target="_blank" rel="noreferrer">Telegram-групу</a> з точним текстом.</p><h2 id="акцентнии-колір" tabindex="-1">Акцентний колір <a class="header-anchor" href="#акцентнии-колір" aria-label="Permalink to &quot;Акцентний колір&quot;">​</a></h2><p>Також у вкладці <strong>Home</strong> ряд із восьми кольорових зразків задає акцентний колір для всього застосунку: Amber, Green, Blue, Purple, Red, Teal, Pink і White. Він діє в усіх вікнах інструментів.</p><p>Це окремо від кольорів свічок і метрик — про них див. <a href="/manual/uk/customize/chart-colors.html">Графіки та рисування</a>.</p><h2 id="оновлення" tabindex="-1">Оновлення <a class="header-anchor" href="#оновлення" aria-label="Permalink to &quot;Оновлення&quot;">​</a></h2><p>Sentaro оновлюється сам. На кожному запуску він перевіряє наявність нової версії перед показом екрана входу; якщо вона є — завантажує, встановлює та перезапускається автоматично. На екрані завантаження при цьому видно <code>Checking for updates...</code>, а потім <code>Updating to v&lt;версія&gt;...</code>.</p><p>Робити нічого не потрібно. Встановлена версія показана у вкладці <strong>Home</strong> як <strong>App Version</strong>.</p><h2 id="де-отримати-допомогу" tabindex="-1">Де отримати допомогу <a class="header-anchor" href="#де-отримати-допомогу" aria-label="Permalink to &quot;Де отримати допомогу&quot;">​</a></h2><p>Повідомлення про помилки та побажання — у <a href="https://t.me/sentaro_trade" target="_blank" rel="noreferrer">групу Telegram</a>. Це найшвидший спосіб отримати пряму відповідь.</p>',21))])}const f=r(i,[["render",d]]);export{k as __pageData,f as default};
